"""FR-05: нэр томьёоны толь — (нэр томьёо, мэргэжлийн тодорхойлолт, жишээ, сэдэв).
Томьёо $...$ (KaTeX). Бодлогын `нэр_томьёо`-нд гарах бүх үг энд байх ёстой."""

GLOSSARY = [
    ('анхны утга', 'Хувиар өөрчлөгдөхөөс өмнөх хэмжигдэхүүний утга; хувийн өөрчлөлт үргэлж анхны утгаас тооцогддог. Өөрчлөгдсөн утга $y$, өсөлт $p\\%$ мэдэгдэж байвал анхны утга $x = \\frac{y}{1 + \\frac{p}{100}}$.', '10%-иар нэмэгдээд 550 болсон бол анхны утга $550 : 1{,}1 = 500$', 'T01'),
    ('бутархай', '$b \\ne 0$ үед $\\frac{a}{b}$ хэлбэрийн тоо; $a$ нь хүртвэр, $b$ нь хуваарь бөгөөд $a$-г $b$-д хуваасан ногдворыг илэрхийлнэ. Үндсэн шинж чанар: $\\frac{a}{b} = \\frac{ak}{bk}$ ($k \\ne 0$).', '$\\frac{6}{8} = \\frac{3}{4}$ — хүртвэр, хуваарийг 2-т хуваав', 'T01'),
    ('бутархай илтгэгч', '$a > 0$, $m$ бүхэл, $n \\ge 2$ натурал үед $a^{\\frac{m}{n}} = \\sqrt[n]{a^m} = \\left(\\sqrt[n]{a}\\right)^m$. Илтгэгчийн хуваарь нь язгуурын зэрэг, хүртвэр нь зэргийн илтгэгч.', '$16^{\\frac{3}{4}} = \\left(\\sqrt[4]{16}\\right)^3 = 2^3 = 8$', 'T01'),
    ('бутархайг үржүүлэх', 'Бутархайг үржүүлэхэд хүртвэрийг хүртвэрээр, хуваарийг хуваариар үржүүлнэ: $\\frac{a}{b} \\cdot \\frac{c}{d} = \\frac{ac}{bd}$ ($b, d \\ne 0$). Ерөнхий хуваарь шаардлагагүй, үржүүлэхээс өмнө хөндлөн хураах нь тооцоог хялбарчилна.', '$\\frac{4}{5} \\cdot \\frac{15}{8} = \\frac{1}{1} \\cdot \\frac{3}{2} = \\frac{3}{2}$', 'T01'),
    ('ерөнхий хуваарь', 'Хэд хэдэн бутархайн хуваарь бүрт хуваагдах тоо (эсвэл илэрхийлэл); бутархайг нэмэх, хасахаас өмнө бүгдийг энэ хуваарьт шилжүүлнэ. Ихэвчлэн хуваариудын хамгийн бага ерөнхий хуваагдагчийг (ХБЕХ) авдаг.', '$\\frac{1}{6} + \\frac{3}{8}$: ХБЕХ$(6, 8) = 24$, $\\frac{4}{24} + \\frac{9}{24}$', 'T01'),
    ('зэргийг задлах', 'Тоо эсвэл суурийг анхны үржигдэхүүнүүдийн зэргийн үржвэр болгон бичих, эсвэл $(ab)^n = a^n b^n$ дүрмээр үржвэрийн зэргийг хүчин зүйлүүдийн зэрэгт хуваах. Ингэснээр ялгаатай суурьтай зэргүүдийг хурааж, харьцуулах боломжтой.', '$12^3 = (4 \\cdot 3)^3 = 2^6 \\cdot 3^3$', 'T01'),
    ('зэргийг хуваах', 'Ижил суурьтай зэргийг хуваахад суурь хэвээр үлдэж, хуваагдагчийн илтгэгчээс хуваагчийн илтгэгчийг хасна: $a^m : a^n = a^{m-n}$ ($a \\ne 0$). Ижил илтгэгчтэй үед $\\frac{a^n}{b^n} = \\left(\\frac{a}{b}\\right)^n$.', '$\\frac{5^7}{5^4} = 5^3 = 125$', 'T01'),
    ('зэргийн зэрэг', 'Зэргийг дахин зэрэгт дэвшүүлэхэд илтгэгчүүд үржигдэнэ: $(a^m)^n = a^{mn}$. Үүнийг ижил суурьтай зэргийн үржвэрийн $a^m \\cdot a^n = a^{m+n}$ (илтгэгч нэмэгдэх) дүрэмтэй андуурч болохгүй.', '$(3^2)^3 = 3^6 = 729$', 'T01'),
    ('зэргийн илтгэгч', '$a^n$ бичлэгт суурийн баруун дээд талд бичигдэх $n$ тоо; натурал $n$ үед суурийг хэдэн удаа үржүүлэхийг заана. Илтгэгч нь тэг, сөрөг, бутархай тоо ч байж болно.', '$7^5$ бичлэгт илтгэгч нь 5, $2^{-3}$-т илтгэгч нь $-3$', 'T01'),
    ('зэргийн суурь', '$a^n$ бичлэгт давтан үржигдэж буй $a$ тоо (эсвэл илэрхийлэл). Сөрөг тоо, бутархай суурьтай зэргийг хаалтанд бичнэ: $(-2)^4 \\ne -2^4$. Бутархай илтгэгчтэй зэрэгт суурь эерэг байх шаардлагатай.', '$(-3)^2 = 9$ бичлэгт суурь нь $-3$', 'T01'),
    ('зэрэг', '$a$ тооны натурал $n$ зэрэг $a^n$ нь $a$-г өөрөөр нь $n$ удаа үржүүлсэн үржвэр; $a^1 = a$, $a \\ne 0$ үед $a^0 = 1$. Сөрөг ба бутархай илтгэгчтэй зэрэг нь энэ тодорхойлолтын өргөтгөл бөгөөд $a^m \\cdot a^n = a^{m+n}$ зэрэг дүрмүүд хадгалагдана.', '$3^4 = 3 \\cdot 3 \\cdot 3 \\cdot 3 = 81$', 'T01'),
    ('квадрат язгуур', '$a \\ge 0$ тооны арифметик квадрат язгуур $\\sqrt{a}$ нь квадрат нь $a$-тай тэнцэх сөрөг биш тоо: $\\sqrt{a} \\ge 0$, $(\\sqrt{a})^2 = a$. Сөрөг тооноос бодит квадрат язгуур гарахгүй, мөн $\\sqrt{x^2} = |x|$.', '$\\sqrt{49} = 7$, учир нь $7 \\ge 0$ ба $7^2 = 49$', 'T01'),
    ('куб язгуур', '$a$ тооны куб язгуур $\\sqrt[3]{a}$ нь куб нь $a$-тай тэнцэх цорын ганц бодит тоо: $\\left(\\sqrt[3]{a}\\right)^3 = a$. Дурын бодит $a$-д, тэр дундаа сөрөг тоонд тодорхойлогдох ба $\\sqrt[3]{a} = a^{\\frac{1}{3}}$ ($a \\ge 0$).', '$\\sqrt[3]{64} = 4$, $\\sqrt[3]{-27} = -3$', 'T01'),
    ('стандарт хэлбэр', 'Тоог $a \\cdot 10^n$ хэлбэрт бичих бичлэг, энд $1 \\le |a| < 10$, $n$ бүхэл тоо. Маш их эсвэл маш бага тоог бичих, үржүүлэхэд $10^m \\cdot 10^n = 10^{m+n}$ дүрмийг ашиглана.', '$45000 = 4{,}5 \\cdot 10^4$, $0{,}003 = 3 \\cdot 10^{-3}$', 'T01'),
    ('сөрөг илтгэгч', '$a \\ne 0$ ба натурал $n$-ийн хувьд $a^{-n} = \\frac{1}{a^n}$ гэж тодорхойлно. Сөрөг илтгэгч нь тоог урвуу тоо руу шилжүүлдэг — тэмдгийг нь өөрчлөхгүй; иймээс $\\left(\\frac{a}{b}\\right)^{-n} = \\left(\\frac{b}{a}\\right)^n$.', '$5^{-2} = \\frac{1}{25}$, $\\left(\\frac{2}{3}\\right)^{-1} = \\frac{3}{2}$', 'T01'),
    ('хуваарь', '$\\frac{a}{b}$ бутархайн зураасын доорх $b$ тоо (эсвэл илэрхийлэл); бүхэл зүйлийг хэдэн тэнцүү хэсэгт хуваасныг заана. Хуваарь хэзээ ч тэгтэй тэнцэж болохгүй.', '$\\frac{5}{7}$-ийн хуваарь 7; $\\frac{1}{x-2}$-т $x \\ne 2$', 'T01'),
    ('хувь', 'Тооны зуугийн нэг хэсэг: $p\\% = \\frac{p}{100}$. Тооны $p\\%$ нь $x \\cdot \\frac{p}{100}$; $p\\%$-иар нэмэгдвэл $x\\left(1 + \\frac{p}{100}\\right)$, буурвал $x\\left(1 - \\frac{p}{100}\\right)$ болно.', '$80$-ын $15\\%$ нь $80 \\cdot 0{,}15 = 12$', 'T01'),
    ('язгуур', '$a$ тооны $n$ зэргийн язгуур $\\sqrt[n]{a}$ нь $n$ зэрэг нь $a$-тай тэнцэх тоо: $\\left(\\sqrt[n]{a}\\right)^n = a$. Тэгш $n$ үед $a \\ge 0$ байх ба язгуур сөрөг биш, сондгой $n$ үед дурын бодит $a$-д тодорхойлогдоно.', '$\\sqrt[4]{81} = 3$, $\\sqrt[3]{-8} = -2$', 'T01'),
    ('язгуураас гаргах', 'Язгуур доорх илэрхийллийн бүтэн квадрат (бүтэн $n$ зэрэг) үржигдэхүүнийг язгуурын өмнө гаргах хувиргалт: $a, b \\ge 0$ үед $\\sqrt{a^2 b} = a\\sqrt{b}$. Язгуур доор аль болох бага тоо үлдээж, төсөөтэй язгууруудыг нэгтгэхэд хэрэглэнэ.', '$\\sqrt{72} = \\sqrt{36 \\cdot 2} = 6\\sqrt{2}$', 'T01'),
    ('язгуурыг үржүүлэх', 'Ижил зэргийн язгуурыг үржүүлэхэд язгуур доорх илэрхийллүүдийг үржүүлнэ: $\\sqrt[n]{a} \\cdot \\sqrt[n]{b} = \\sqrt[n]{ab}$ ($a, b \\ge 0$). Энэ нь нэмэхэд хүчингүй: $\\sqrt{a} + \\sqrt{b} \\ne \\sqrt{a+b}$.', '$\\sqrt{2} \\cdot \\sqrt{8} = \\sqrt{16} = 4$', 'T01'),
    ('үйлдлийн дараалал', 'Илэрхийллийн утгыг бодох тогтсон дараалал: хаалт → зэрэг ба язгуур → үржих, хуваах (зүүнээс баруун) → нэмэх, хасах (зүүнээс баруун). Хаалт нь энэ дарааллыг өөрчлөх цорын ганц арга.', '$10 - 2 \\cdot 3^2 = 10 - 18 = -8$', 'T01'),
    ('бүлэглэх арга', 'Олон гишүүнтийн гишүүдийг ерөнхий үржигдэхүүнтэй бүлгүүдэд хуваан, бүлэг бүрээс үржигдэхүүн гаргах замаар задлах арга. Бүлгүүдэд ижил хаалт үүсвэл $ac + bc = (a + b)c$ дүрмээр түүнийг гаргаж задлалыг гүйцээнэ.', '$ax + ay + 2x + 2y = a(x+y) + 2(x+y) = (x+y)(a+2)$', 'T02'),
    ('бүтэн квадрат ялгах', '$x^2 + px + q$ гурван гишүүнтийг $\\left(x + \\frac{p}{2}\\right)^2 + q - \\frac{p^2}{4}$ хэлбэрт хувиргах арга. Квадрат тэгшитгэл бодох, хамгийн бага (их) утга олох, параболын оройг тодорхойлоход хэрэглэнэ.', '$x^2 + 4x + 7 = (x + 2)^2 + 3$', 'T02'),
    ('ерөнхий үржигдэхүүн', 'Олон гишүүнтийн бүх гишүүнд үржигдэхүүн болж орсон тоо эсвэл илэрхийлэл; хаалтын өмнө гаргахдаа $ab + ac = a(b + c)$ гэж бичнэ. Хамгийн их ерөнхий үржигдэхүүн нь коэффициентуудын ХИЕХ ба хувьсагч бүрийн хамгийн бага зэргийн үржвэр.', '$8x^3 - 12x^2 = 4x^2(2x - 3)$', 'T02'),
    ('илэрхийллийн утга', 'Хувьсагчийн оронд өгөгдсөн тоог орлуулж, үйлдлийн дарааллаар бодсоны дүнд гарах тоо. Утга нь зөвхөн тодорхойлогдох мужид (жишээ нь хуваарь тэг биш үед) оршино.', '$x = 3$ үед $2x^2 - x = 18 - 3 = 15$', 'T02'),
    ('квадрат гурван гишүүнт', '$ax^2 + bx + c$ ($a \\ne 0$) хэлбэрийн олон гишүүнт; $a$, $b$, $c$ нь коэффициентууд, $c$ нь сул гишүүн. $D = b^2 - 4ac \\ge 0$ үед $a(x - x_1)(x - x_2)$ хэлбэрт задарна, энд $x_1$, $x_2$ нь түүний язгуурууд.', '$x^2 - x - 6 = (x - 3)(x + 2)$', 'T02'),
    ('квадратуудын ялгавар', 'Хоёр илэрхийллийн квадратуудын ялгаврын томьёо: $a^2 - b^2 = (a - b)(a + b)$. Үржигдэхүүнд задлах болон тооцоог хялбарчлахад хэрэглэнэ; квадратуудын нийлбэр $a^2 + b^2$ бодит үржигдэхүүнд ингэж задрахгүй.', '$9y^2 - 1 = (3y - 1)(3y + 1)$', 'T02'),
    ('коэффициент', 'Гишүүний үсэгтэй хэсгийн өмнөх тоон үржигдэхүүн. Тоо бичигдээгүй бол коэффициент нь 1, ганц хасах тэмдэгтэй бол $-1$; сул гишүүн нь хувьсагчгүй гишүүн.', '$-7x^2y$-ийн коэффициент $-7$; $x$-ийн коэффициент 1', 'T02'),
    ('нийлбэрийн квадрат', 'Хоёр илэрхийллийн нийлбэрийн квадратын томьёо: $(a+b)^2 = a^2 + 2ab + b^2$. Дунд гишүүн $2ab$ нь давхар үржвэр бөгөөд $(a+b)^2 \\ne a^2 + b^2$.', '$(y + 5)^2 = y^2 + 10y + 25$', 'T02'),
    ('нийлбэрийн куб', 'Хоёр илэрхийллийн нийлбэрийн кубын томьёо: $(a+b)^3 = a^3 + 3a^2 b + 3ab^2 + b^3$. Коэффициентууд 1, 3, 3, 1 бөгөөд $(a+b)^3 \\ne a^3 + b^3$.', '$(y + 1)^3 = y^3 + 3y^2 + 3y + 1$', 'T02'),
    ('орлуулах', 'Илэрхийлэл дэх хувьсагчийг өгөгдсөн тоо эсвэл өөр илэрхийллээр солих үйлдэл. Сөрөг тоо, нийлбэрийг орлуулахдаа заавал хаалтанд хийж, дараа нь үйлдлийн дарааллаар бодно.', '$x = -1$-ийг $x^2 + 4x$-д: $(-1)^2 + 4 \\cdot (-1) = -3$', 'T02'),
    ('рационал илэрхийлэл', 'Олон гишүүнтүүдийн ногдвор $\\frac{P(x)}{Q(x)}$ хэлбэрийн илэрхийлэл. Хуваарийг тэг болгох утгууд тодорхойлогдох мужид орохгүй; хураах, нэмэх зэрэг үйлдлийг энгийн бутархайн дүрмээр гүйцэтгэнэ.', '$\\frac{x+1}{x^2 - 4}$, тодорхойлогдох муж: $x \\ne \\pm 2$', 'T02'),
    ('сөрөг тоо', 'Тэгээс бага бодит тоо; тоон шулуун дээр тэгээс зүүн талд байрлана. Тэмдгийн дүрэм: хоёр сөрөг тооны үржвэр эерэг, сөрөг тооны тэгш зэрэг эерэг, сондгой зэрэг сөрөг; $(-a)^2 \\ne -a^2$.', '$(-3)^2 = 9$, харин $-3^2 = -9$; $(-2)^3 = -8$', 'T02'),
    ('товчилсон үржвэрийн томьёо', 'Олон гишүүнтүүдийн түгээмэл үржвэрийг шууд бичих адилтгалууд: $(a \\pm b)^2 = a^2 \\pm 2ab + b^2$, $(a-b)(a+b) = a^2 - b^2$, $(a \\pm b)^3 = a^3 \\pm 3a^2b + 3ab^2 \\pm b^3$. Зүүнээс баруун тийш хэрэглэвэл хаалт задлах, эсрэгээр хэрэглэвэл үржигдэхүүнд задлах болно.', '$(m - 2)(m + 2) = m^2 - 4$', 'T02'),
    ('төсөөтэй гишүүн', 'Үсэгтэй хэсэг нь (хувьсагчид ба тэдгээрийн илтгэгч) яг ижил, зөвхөн коэффициентоороо ялгаатай гишүүд. Зөвхөн төсөөтэй гишүүдийг $ma + na = (m+n)a$ хуулиар нэгтгэж болно.', '$5xy$ ба $-2xy$ төсөөтэй; $3x$ ба $3x^2$ төсөөтэй биш', 'T02'),
    ('хаалт задлах', 'Хаалттай илэрхийллийг хуваарилах хууль $a(b + c) = ab + ac$ болон товчилсон үржвэрийн томьёогоор хаалтгүй олон гишүүнт болгох хувиргалт. Хаалтын өмнөх үржигдэхүүн доторх гишүүн бүрийг тэмдэгтэй нь үржүүлнэ.', '$-2(x - 3) = -2x + 6$', 'T02'),
    ('хасах тэмдэг хаалтын өмнө', 'Хаалтын өмнөх хасах тэмдэг нь хаалтыг $-1$-ээр үржүүлж буйтай адил: $-(a - b + c) = -a + b - c$. Хаалт задлахад доторх бүх гишүүний тэмдэг эсрэгээр солигдоно.', '$-(2x - 7) = -2x + 7$', 'T02'),
    ('хураах', 'Бутархайн хүртвэр, хуваарийг ижил тэгээс ялгаатай ерөнхий үржигдэхүүнд хуваах хувиргалт: $\\frac{ac}{bc} = \\frac{a}{b}$ ($c \\ne 0$). Зөвхөн үржигдэхүүнийг хураана — нэмэгдэхүүнийг хурааж болохгүй, тиймээс эхлээд үржигдэхүүнд задална.', '$\\frac{3x}{6x^2} = \\frac{1}{2x}$ ($x \\ne 0$)', 'T02'),
    ('ялгаврын квадрат', 'Хоёр илэрхийллийн ялгаврын квадратын томьёо: $(a-b)^2 = a^2 - 2ab + b^2$. Дунд гишүүн $-2ab$ заавал байх бөгөөд $b^2$ гишүүн үргэлж эерэг тэмдэгтэй.', '$(3y - 2)^2 = 9y^2 - 12y + 4$', 'T02'),
    ('үржигдэхүүнд задлах', 'Олон гишүүнт (эсвэл тоо)-ийг хэд хэдэн хүчин зүйлийн үржвэр хэлбэрт бичих хувиргалт. Гол аргууд: ерөнхий үржигдэхүүнийг гаргах, бүлэглэх, товчилсон үржвэрийн томьёо хэрэглэх; үр дүнг буцааж үржүүлэхэд анхны илэрхийлэл гарна.', '$x^2 - 5x = x(x - 5)$, $a^2 - 1 = (a-1)(a+1)$', 'T02'),
    ('аравтын бутархай', 'Хуваарь нь $10^n$ байх бутархайг таслалтай бичих хэлбэр. Аравтын бутархайтай тэгшитгэлийг хоёр талыг $10$, $100$ эсвэл тохирох тоогоор үржүүлж бүхэл коэффициенттэй болгож болно.', '$0{,}5x = 1{,}5 \\Rightarrow 5x = 15$', 'T03'),
    ('дараалсан тоо', 'Бие биенээсээ ижил алхмаар ялгаатай, дараалан ирэх бүхэл тоонууд. Дараалсан натурал тоонуудыг $n,\\ n+1,\\ n+2, \\dots$, дараалсан тэгш (сондгой) тоонуудыг $n,\\ n+2,\\ n+4, \\dots$ гэж бичнэ.', '$14, 15, 16$ — дараалсан натурал тоо', 'T03'),
    ('зам', 'Хөдөлгөөний явцад биеийн туулсан зайн урт. Жигд хөдөлгөөнд $s = v \\cdot t$; хэд хэдэн хэсгээс тогтвол нийт зам нь хэсгүүдийн замын нийлбэр.', '$80$ км/ц хурдтай $3$ цаг: $s = 80 \\cdot 3 = 240$ км', 'T03'),
    ('нэмэх арга', 'Тэгшитгэлийн системийг бодох арга: тэгшитгэлүүдийг шаардлагатай бол тоогоор үржүүлж нэг хувьсагчийн коэффициентуудыг эсрэг тоо болгоод гишүүнчлэн нэмнэ. Тэр хувьсагч устаж, нэг хувьсагчтай тэгшитгэл үлдэнэ.', '$x + y = 7$, $x - y = 1$ нэмбэл $2x = 8$', 'T03'),
    ('орлуулах арга', 'Тэгшитгэлийн системийг бодох арга: нэг тэгшитгэлээс нэг хувьсагчийг нөгөөгөөр нь илэрхийлээд, үлдсэн тэгшитгэлд орлуулна. Нэг хувьсагчтай тэгшитгэл гарч, түүнийг бодоод буцаан орлуулж нөгөө хувьсагчийг олно.', '$y = x + 1$, $x + y = 5$ $\\Rightarrow x + (x + 1) = 5$', 'T03'),
    ('пропорц', 'Хоёр харьцааны тэнцүү: $\\frac{a}{b} = \\frac{c}{d}$ ($b, d \\ne 0$). Үндсэн чанар: хөндлөн (захын ба дундын) гишүүдийн үржвэрүүд тэнцүү, $ad = bc$.', '$\\frac{3}{4} = \\frac{9}{12}$, учир нь $3 \\cdot 12 = 4 \\cdot 9$', 'T03'),
    ('сөрөг коэффициент', 'Хувьсагчийн өмнөх тоон үржигдэхүүн сөрөг байх тохиолдол. Ийм тэгшитгэлийг бодохдоо хоёр талыг сөрөг коэффициентод хуваахад тэмдгийн дүрмийг баримтална: сөрөгийг сөрөгт хуваавал эерэг.', '$-2x = -6$: $x$-ийн коэффициент $-2$', 'T03'),
    ('тэгшитгэл', 'Үл мэдэгдэгч агуулсан, хоёр илэрхийллийн тэнцүүг илэрхийлсэн тэнцэтгэл. Тэгшитгэлийг бодно гэдэг нь түүний бүх язгуурыг олох эсвэл язгуургүйг батлах явдал. Ижил шийдтэй тэгшитгэлүүдийг тэнцүү чанартай гэнэ.', '$3x - 7 = 2x + 1$ — нэг үл мэдэгдэгчтэй шугаман тэгшитгэл', 'T03'),
    ('тэгшитгэл зохиох', 'Бодлогын нөхцөлд байгаа хэмжигдэхүүн хоорондын тэнцүү хамаарлыг үл мэдэгдэгч ашиглан математик тэнцэтгэлээр илэрхийлэх. Нэг хэмжигдэхүүнийг $x$ гээд бусдыг нь $x$-ээр илэрхийлж, тэнцүү хоёр илэрхийллийг олно.', 'Үзэг $x$, дэвтэр $x + 300$; 2 дэвтэр, 3 үзэг 3600: $2(x + 300) + 3x = 3600$', 'T03'),
    ('тэгшитгэлийн систем', 'Нэгэн зэрэг биелэх ёстой хэд хэдэн тэгшитгэл; ихэвчлэн их хаалтаар бичнэ. Системийн шийд нь бүх тэгшитгэлийг зэрэг хангах хувьсагчдын утгын олонлог (жишээ нь $(x; y)$ хос).', '$\\begin{cases} x + y = 5 \\\\ x - y = 1 \\end{cases}$ шийд нь $(3; 2)$', 'T03'),
    ('хугацаа', 'Хөдөлгөөн (үйл явц) үргэлжлэх хугацааны урт; жигд хөдөлгөөнд $t = \\frac{s}{v}$. Хурдны нэгжтэй нийцүүлж (цаг, секунд) илэрхийлнэ.', '$150$ км-ийг $50$ км/ц хурдтай: $t = 3$ цаг', 'T03'),
    ('хурд', 'Хөдөлж буй биеийн нэгж хугацаанд туулах зам; жигд хөдөлгөөнд $v = \\frac{s}{t}$. Нэгж нь км/ц, м/с гэх мэт; бодлогод бүх хэмжигдэхүүнийг ижил нэгжээр илэрхийлэх ёстой.', '$120$ км-ийг $2$ цагт туулбал $v = 60$ км/ц', 'T03'),
    ('хөндлөн үржүүлэх', '$\\frac{a}{b} = \\frac{c}{d}$ ($b, d \\ne 0$) пропорцыг $ad = bc$ хэлбэрт шилжүүлэх хувиргалт. Энэ нь хоёр талыг $bd$-ээр үржүүлсэнтэй тэнцүү бөгөөд зөвхөн хоёр бутархайн тэнцүүд хэрэглэгдэнэ.', '$\\frac{x}{3} = \\frac{4}{6} \\Rightarrow 6x = 12$', 'T03'),
    ('шилжүүлэх', 'Тэгшитгэлийн гишүүнийг тэнцүүгийн нэг талаас нөгөө тал руу эсрэг тэмдэгтэйгээр зөөх хувиргалт. Хоёр талд ижил тоо нэмэх (хасах)-тай адил тул шийдийг өөрчлөхгүй: $a + b = c \\iff a = c - b$.', '$x + 5 = 7 \\Rightarrow x = 7 - 5$', 'T03'),
    ('үгэн бодлого', 'Нөхцөл нь үгээр өгөгдсөн, математик загвар (тэгшитгэл, систем) зохиож бодох бодлого. Үе шат: үл мэдэгдэгчийг сонгох, бусад хэмжигдэхүүнийг түүгээр илэрхийлэх, тэгшитгэл зохиож бодох, хариуг нөхцөлтэй тулгах.', '«Нэг тоо нөгөөгөөсөө 2-оор их, нийлбэр нь 10» $\\Rightarrow x + (x + 2) = 10$', 'T03'),
    ('үл мэдэгдэгч', 'Тэгшитгэлд утга нь тодорхойгүй, олох шаардлагатай хэмжигдэхүүн; ихэвчлэн $x$, $y$, $z$ үсгээр тэмдэглэнэ. Тэгшитгэлийг бодох нь үл мэдэгдэгчийн тэнцэтгэлийг үнэн болгох бүх утгыг олох явдал.', '$2x = 6$-д $x$ үл мэдэгдэгч, $x = 3$ үед тэнцэтгэл үнэн', 'T03'),
    ('Виетийн теорем', '$x^2 + px + q = 0$ тэгшитгэл $x_1$, $x_2$ язгууртай бол $x_1 + x_2 = -p$, $x_1 x_2 = q$. Ерөнхий $ax^2 + bx + c = 0$-д $x_1 + x_2 = -\\frac{b}{a}$, $x_1 x_2 = \\frac{c}{a}$. Урвуу теоремоор язгуурыг таамаглан олж болно.', '$x^2 - 5x + 6 = 0$: $2 + 3 = 5$, $2 \\cdot 3 = 6$ — язгуурууд $2$ ба $3$', 'T04'),
    ('биквадрат тэгшитгэл', '$ax^4 + bx^2 + c = 0$ ($a \\ne 0$) хэлбэрийн тэгшитгэл. $t = x^2$ ($t \\ge 0$) орлуулгаар квадрат тэгшитгэлд шилжүүлж бодно; $t$-ийн эерэг язгуур бүр $x = \\pm\\sqrt{t}$ хоёр язгуур өгнө.', '$x^4 - 10x^2 + 9 = 0$: $t^2 - 10t + 9 = 0$', 'T04'),
    ('давхар язгуур', 'Квадрат тэгшитгэлийн $D = 0$ үеийн давхацсан хоёр язгуур: $x_1 = x_2 = -\\frac{b}{2a}$. Энэ үед $ax^2 + bx + c = a(x - x_0)^2$ бөгөөд парабол $Ox$ тэнхлэгт шүргэнэ.', '$x^2 - 4x + 4 = (x - 2)^2 = 0$: давхар язгуур $x = 2$', 'T04'),
    ('дискриминант', '$ax^2+bx+c=0$ ($a \\ne 0$) квадрат тэгшитгэлийн $D = b^2 - 4ac$ илэрхийлэл. Бодит язгуурын тоог тодорхойлно: $D>0$ бол хоёр ялгаатай, $D=0$ бол нэг давхар, $D<0$ бол бодит язгуургүй.', '$x^2 + 2x + 1 = 0$: $D = 4 - 4 = 0$ — давхар язгууртай', 'T04'),
    ('иррационал язгуур', 'Иррационал тоо болох тэгшитгэлийн язгуур, өөрөөр хэлбэл $\\frac{p}{q}$ бутархайгаар илэрхийлэгдэхгүй язгуур. Бүхэл коэффициенттэй квадрат тэгшитгэлийн $D > 0$ нь бүтэн квадрат биш үед гарна; $m \\pm n\\sqrt{k}$ хэлбэрээр бичнэ.', '$x^2 = 2$-ийн язгуурууд $\\pm\\sqrt{2}$ — иррационал', 'T04'),
    ('квадрат тэгшитгэл', '$ax^2 + bx + c = 0$ хэлбэрийн тэгшитгэл; энд $a, b, c$ — тоо, $a \\ne 0$. $b = 0$ эсвэл $c = 0$ бол бүрэн биш квадрат тэгшитгэл гэнэ. Хамгийн ихдээ хоёр бодит язгууртай.', '$x^2 - 5x + 6 = 0$: $a = 1$, $b = -5$, $c = 6$', 'T04'),
    ('квадрат тэгшитгэлийн томьёо', '$ax^2 + bx + c = 0$ ($a \\ne 0$) тэгшитгэлийн язгуурын ерөнхий томьёо: $x_{1,2} = \\frac{-b \\pm \\sqrt{D}}{2a}$, $D = b^2 - 4ac$. Зөвхөн $D \\ge 0$ үед бодит язгуур өгнө; бүтэн квадрат ялгах замаар гаргана.', '$2x^2 - 5x + 2 = 0$: $x = \\frac{5 \\pm 3}{4}$', 'T04'),
    ('параметр', 'Тэгшитгэлд үсгээр тэмдэглэгдсэн боловч үл мэдэгдэгч биш, тогтмол гэж үзэх хэмжигдэхүүн. Параметрийн утгаас хамаарч шийдийн тоо, утга өөрчлөгдөх тул «ямар параметрт ... нөхцөл биелэх вэ» гэж судална.', '$x^2 + kx + 9 = 0$-д $k$ параметр; $D = k^2 - 36$', 'T04'),
    ('талбай', 'Хавтгай дүрсийн эзлэх хэсгийн хэмжээ, квадрат нэгжээр ($\\text{см}^2$, $\\text{м}^2$) хэмжинэ. Тэгш өнцөгтийнх $S = a \\cdot b$, квадратынх $S = a^2$; талуудын холбоо өгөгдвөл квадрат тэгшитгэлд хүргэдэг.', 'Тал нь $x$ ба $x + 2$, талбай $15$: $x(x + 2) = 15$', 'T04'),
    ('хаалтын өмнө гаргах', 'Олон гишүүнтийн бүх гишүүнд байгаа ерөнхий үржигдэхүүнийг хаалтын гадна бичиж үржвэр болгох хувиргалт: $ab + ac = a(b + c)$. Хуваарилах чанарын урвуу үйлдэл бөгөөд $A \\cdot B = 0$ хэлбэрт оруулахад хэрэглэнэ.', '$x^2 - 5x = x(x - 5)$', 'T04'),
    ('шийдийн тоо', 'Тэгшитгэлийн ялгаатай бодит язгууруудын тоо. Квадрат тэгшитгэлийн хувьд дискриминантын тэмдгээр тодорхойлогдоно: $D > 0$ — хоёр, $D = 0$ — нэг, $D < 0$ — бодит шийдгүй.', '$x^2 + 1 = 0$: $D = -4 < 0$, бодит шийд $0$', 'T04'),
    ('язгуур (тэгшитгэлийн)', 'Тэгшитгэлд орлуулахад түүнийг үнэн тоон тэнцэтгэл болгох үл мэдэгдэгчийн утга; шийд гэж ч нэрлэнэ. Квадрат тэгшитгэл хоёроос илүүгүй бодит язгууртай.', '$x = 2$ ба $x = -2$ нь $x^2 = 4$-ийн язгуурууд', 'T04'),
    ('язгууруудын нийлбэр ба үржвэр', '$ax^2 + bx + c = 0$ тэгшитгэлийн язгуурууд $x_1 + x_2 = -\\frac{b}{a}$, $x_1 x_2 = \\frac{c}{a}$ (Виетийн теорем). Язгуурын тэгш хэмт илэрхийллийг эдгээрээр олно, жишээ нь $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1 x_2$.', '$x^2 - 4x + 3 = 0$: нийлбэр $4$, үржвэр $3$', 'T04'),
    ('давхар тэнцэтгэл биш', '$a < f(x) < b$ хэлбэрийн, хоёр нөхцлийг зэрэг илэрхийлсэн тэнцэтгэл биш. Гурван хэсэгт ижил үйлдлийг зэрэг хийж $x$-ийг дунд нь ганцаарчилна; сөрөг тоонд хуваахад хоёр тэмдэг хоёулаа эргэнэ.', '$1 < 2x + 3 < 7 \\iff -1 < x < 2$', 'T05'),
    ('завсар', 'Тоон шулууны хоёр цэгийн хоорондох бүх бодит тоон олонлог. Захыг оруулбал дөрвөлжин $[\\,]$, оруулахгүй бол дугуй $(\\,)$ хаалт хэрэглэнэ; хязгааргүй завсарт $\\infty$ талд үргэлж дугуй хаалт тавина. Тэнцэтгэл бишийн шийдийг завсраар бичдэг.', '$-1 \\le x < 3 \\iff x \\in [-1; 3)$', 'T05'),
    ('интервалын арга', '$\\frac{P(x)}{Q(x)}$ эсвэл үржвэр хэлбэрийн тэнцэтгэл бишийг бодох арга: хүртвэр ба хуваарийн тэгүүдээр тоон шулууныг завсруудад хувааж, завсар бүрт илэрхийллийн тэмдгийг тогтооно. Тэмдэг зөвхөн эдгээр чухал цэгүүд дээр өөрчлөгдөж болно.', '$(x-1)(x-3) < 0$: цэгүүд $1, 3$ → шийд $1 < x < 3$', 'T05'),
    ('квадрат тэнцэтгэл биш', '$ax^2 + bx + c > 0$ ($<$, $\\le$, $\\ge$), $a \\ne 0$ хэлбэрийн тэнцэтгэл биш. Язгуурыг олж, параболын чиглэлийг ($a$-гийн тэмдэг) ашиглан илэрхийлэл эерэг, сөрөг байх завсруудыг тодорхойлно. $a > 0$, $D > 0$ үед язгууруудын хооронд сөрөг, гадна эерэг.', '$x^2 - 1 < 0 \\iff -1 < x < 1$', 'T05'),
    ('модуль', 'Бодит тоо $a$-ийн модуль $|a| = a$ ($a \\ge 0$ үед), $|a| = -a$ ($a < 0$ үед). Геометрээр тоон шулуун дээрх $a$ цэгээс $0$ хүртэлх зай, $|a - b|$ нь $a$ ба $b$-ийн хоорондох зай. Үргэлж $|a| \\ge 0$.', '$|-5| = 5$; $|x| < 2 \\iff -2 < x < 2$', 'T05'),
    ('нэгдэл', '$A \\cup B$ — $A$ эсвэл $B$-ийн ядаж нэгд нь орох бүх элементийн олонлог. Тэнцэтгэл бишид \\"эсвэл\\" холбоосоор холбогдсон нөхцлүүдийн шийдийг илэрхийлнэ.', '$x < -1$ эсвэл $x > 2$: $(-\\infty; -1) \\cup (2; +\\infty)$', 'T05'),
    ('огтлолцол', '$A \\cap B$ — $A$ ба $B$ хоёуланд нь зэрэг орох элементийн олонлог. Тэнцэтгэл бишийн системд \\"ба\\" холбоосоор холбогдсон нөхцлүүдийн шийдийг илэрхийлнэ; тоон шулуун дээр давхцсан хэсэг юм.', '$[0; 5] \\cap (3; 8) = (3; 5]$', 'T05'),
    ('рационал тэнцэтгэл биш', '$\\frac{P(x)}{Q(x)} > 0$ ($<$, $\\le$, $\\ge$) хэлбэрийн тэнцэтгэл биш, $P$, $Q$ олон гишүүнт. Хуваарийн тэмдэг тодорхойгүй тул түүгээр үржүүлэхгүй, интервалын аргаар бодно; $Q(x) = 0$ болгох цэгүүд шийдэд хэзээ ч орохгүй.', '$\\frac{x}{x - 1} < 0 \\iff 0 < x < 1$', 'T05'),
    ('сөрөг тоонд хуваах', 'Тэнцэтгэл бишийн хоёр талыг сөрөг тоо $c$-д хуваах (үржүүлэх) үед тэмдэг эсрэгээр эргэнэ: $a < b,\\ c < 0 \\Rightarrow \\frac{a}{c} > \\frac{b}{c}$. Учир нь сөрөг тоогоор үржүүлэхэд тоон шулуун дээрх дараалал урвуу болдог.', '$-2x < 6 \\Rightarrow x > -3$', 'T05'),
    ('тэнцэтгэл биш', 'Хоёр илэрхийллийг $<$, $>$, $\\le$, $\\ge$ тэмдгээр холбосон өгүүлбэр. Шийд нь түүнийг үнэн болгох хувьсагчийн бүх утгын олонлог бөгөөд ихэвчлэн завсар хэлбэртэй. Хоёр талд ижил тоо нэмэхэд эсвэл эерэг тоогоор үржүүлэхэд тэмдэг хэвээр, сөрөг тоогоор үржүүлэхэд эргэнэ.', '$2x > 6 \\iff x > 3$, шийд нь $(3; +\\infty)$', 'T05'),
    ('тэнцэтгэл бишийн систем', 'Нэг хувьсагчийн хувьд зэрэг биелэх ёстой хэд хэдэн тэнцэтгэл биш, их хаалтаар бичнэ. Шийд нь тэнцэтгэл биш тус бүрийн шийдүүдийн огтлолцол; огтлолцол хоосон бол систем шийдгүй.', '$x > 1$ ба $x < 5$ системийн шийд: $1 < x < 5$', 'T05'),
    ('тэнцэтгэл бишийн тэмдэг', '$<$ (бага), $>$ (их) — хатуу тэмдэг, хил орохгүй; $\\le$, $\\ge$ — сул тэмдэг, хил орно. Сөрөг тоогоор үржүүлэх, хуваахад тэмдэг эсрэгээр эргэнэ; тоон шулуун дээр хатуу хилийг хоосон, сул хилийг дүүрэн дугуйгаар тэмдэглэнэ.', '$x \\le 2$: $2$ орно; $x < 2$: $2$ орохгүй', 'T05'),
    ('эерэг тоонд хуваах', 'Тэнцэтгэл бишийн хоёр талыг эерэг тоо $c$-д хуваах (үржүүлэх) үед тэмдэг хэвээр үлдэнэ: $a < b,\\ c > 0 \\Rightarrow \\frac{a}{c} < \\frac{b}{c}$. Энэ нь $x$-ийг ганцаарчлахад хэрэглэгдэнэ.', '$4x \\ge 8 \\Rightarrow x \\ge 2$', 'T05'),
    ('Ox тэнхлэгтэй огтлолцох', 'Функцийн график $Ox$ тэнхлэгийг $y = 0$ үед огтолно; цэгүүдийн абсцисс нь $f(x) = 0$ тэгшитгэлийн язгуурууд. Ийм цэг байхгүй, нэг эсвэл хэд хэд байж болно.', '$y = x^2 - 1$: $(-1; 0)$ ба $(1; 0)$', 'T06'),
    ('Oy тэнхлэгтэй огтлолцох', 'Функцийн график $Oy$ тэнхлэгийг $x = 0$ үед огтолно; огтлолцлын цэг $(0; f(0))$. Функц $x = 0$ үед тодорхойлогдох бол ийм цэг яг нэг байна. $y = kx + b$-д энэ нь $(0; b)$.', '$y = 2x - 5$: $(0; -5)$', 'T06'),
    ('аргумент', 'Функцийн бие даасан хувьсагч — $y = f(x)$-д $x$. Аргумент тодорхойлогдох мужаас утга авах бөгөөд түүний утга бүрт функцийн нэг утга харгалзана.', '$f(x) = 3x$-д $x = 2$ аргументад $f(2) = 6$', 'T06'),
    ('буурах функц', 'Завсар дахь дурын $x_1 < x_2$-ийн хувьд $f(x_1) > f(x_2)$ байвал $f$ энэ завсарт буурах функц. График зүүнээс баруун тийш доошилно.', '$y = -3x + 2$ бүх тоон шулуун дээр буурна', 'T06'),
    ('давхар функц', 'Нэг функцийн утгыг нөгөө функцийн аргумент болгосон нийлмэл функц $f(g(x))$; функцийн найрлагатай ижил ойлголт. Дотоод функц $g$ эхэлж, гадаад функц $f$ дараа нь хэрэглэгдэнэ.', '$f(x) = x + 1$, $g(x) = x^2$: $f(g(3)) = 10$', 'T06'),
    ('квадрат функц', '$f(x) = ax^2 + bx + c$ ($a \\ne 0$) хэлбэрийн функц. График нь парабол; $a$ нь чиглэл ба өргөнийг, $c$ нь $Oy$-тэй огтлолцох цэгийг, дискриминант $D$ нь $Ox$-тэй огтлолцох цэгийн тоог тодорхойлно.', '$f(x) = x^2 - 4x + 3$: $a = 1$, $b = -4$, $c = 3$', 'T06'),
    ('налалт', 'Шулууны хазайлтын хэмжүүр буюу өнцгийн коэффициент: $k = \\frac{\\Delta y}{\\Delta x} = \\frac{y_2 - y_1}{x_2 - x_1}$. $x$ нэгээр өөрчлөгдөхөд $y$ хэдээр өөрчлөгдөхийг заана; эерэг бол шулуун өгсөнө, сөрөг бол уруудна.', '$(0; 1)$, $(1; 4)$ цэгүүд: налалт $\\frac{4 - 1}{1 - 0} = 3$', 'T06'),
    ('оройн цэг', 'Параболын хамгийн доод ($a > 0$) эсвэл хамгийн дээд ($a < 0$) цэг. $y = ax^2 + bx + c$-д $x_0 = -\\frac{b}{2a}$, $y_0 = f(x_0)$; $y = a(x - x_0)^2 + y_0$ хэлбэрээс шууд уншигдана.', '$y = (x - 1)^2 + 2$: орой $(1; 2)$', 'T06'),
    ('парабол', '$y = ax^2 + bx + c$ ($a \\ne 0$) квадрат функцийн график. $a > 0$ бол салаа нь дээш, $a < 0$ бол доош харна. Орой нь $x_0 = -\\frac{b}{2a}$ цэгт, тэгш хэмийн тэнхлэг нь $x = x_0$ шулуун.', '$y = x^2$: орой $(0; 0)$, салаа дээш', 'T06'),
    ('параллель шулуун', 'Нэг хавтгайд орших, огтлолцохгүй шулуунууд. $y = k_1x + b_1$ ба $y = k_2x + b_2$ параллель $\\iff k_1 = k_2$ ба $b_1 \\ne b_2$.', '$y = 2x + 1$ ба $y = 2x - 4$ параллель', 'T06'),
    ('тодорхойлогдох муж', 'Функцийн томьёо утгатай байх аргументын бүх утгын олонлог, $D(f)$ гэж тэмдэглэнэ. Олохдоо хуваарь $\\ne 0$, тэгш зэргийн язгуур доорх илэрхийлэл $\\ge 0$, логарифмын доорх илэрхийлэл $> 0$ гэх мэт нөхцлүүдийг тавина.', '$\\sqrt{x - 1}$: $x \\ge 1$; $\\frac{1}{x}$: $x \\ne 0$', 'T06'),
    ('тэгш хэмийн тэнхлэг', 'Графикийг тусгахад өөртэйгөө давхцдаг шулуун. $y = ax^2 + bx + c$ параболын тэгш хэмийн тэнхлэг нь орой дундуур гарах босоо шулуун $x = -\\frac{b}{2a}$; тэнхлэгээс ижил зайтай $x$-үүдэд функцийн утга тэнцүү.', '$y = x^2 - 4x$: тэнхлэг $x = 2$, $f(1) = f(3)$', 'T06'),
    ('функц', '$X$ олонлогийн элемент $x$ бүрт $Y$ олонлогийн яг нэг элемент $y = f(x)$-ийг харгалзуулах дүрэм. $x$-ийг аргумент, $y$-ийг функцийн утга, $X$-ийг тодорхойлогдох муж гэнэ. Нэг $x$-д хоёр өөр $y$ харгалзаж болохгүй.', '$f(x) = 2x + 1$: $f(3) = 7$', 'T06'),
    ('функцийн найрлага', '$(f \\circ g)(x) = f(g(x))$ — эхлээд $g$, дараа нь $f$-ийг хэрэглэсэн функц. $g(x)$ нь $f$-ийн тодорхойлогдох мужид орох ёстой. Ерөнхийдөө $f(g(x)) \\ne g(f(x))$.', '$f(x) = 2x$, $g(x) = x + 1$: $f(g(1)) = 4$, $g(f(1)) = 3$', 'T06'),
    ('функцийн тэг', '$f(x) = 0$ байх аргументын утга, өөрөөр хэлбэл $f(x) = 0$ тэгшитгэлийн язгуур. Геометрээр график $Ox$ тэнхлэгтэй огтлолцох (шүргэх) цэгийн абсцисс.', '$f(x) = x - 2$-ийн тэг: $x = 2$', 'T06'),
    ('функцийн утга', 'Аргументын тодорхой утга $x = a$-д харгалзах $f(a)$ тоо; томьёонд $x$-ийн оронд $a$-г орлуулж олно. Функцийн бүх утгын олонлогийг утгын муж $E(f)$ гэнэ.', '$f(x) = x^2 + 1$ бол $f(2) = 5$', 'T06'),
    ('хамгийн их утга', 'Функцийн тодорхойлогдох муж (эсвэл өгөгдсөн завсар) дахь бүх утгаас их буюу тэнцүү утга: бүх $x$-д $f(x) \\le f(x_0)$. $a < 0$ үед квадрат функц хамгийн их утгаа оройд авна.', '$y = -x^2 + 3$-ийн хамгийн их утга $3$ ($x = 0$ үед)', 'T06'),
    ('хуваарь тэг байж болохгүй', 'Тэгд хуваах үйлдэл тодорхойлогдоогүй тул $\\frac{P(x)}{Q(x)}$ бутархай зөвхөн $Q(x) \\ne 0$ үед утгатай. Иймд $Q(x) = 0$-ийн язгууруудыг тодорхойлогдох мужаас хасна.', '$\\frac{1}{x + 2}$: $x \\ne -2$', 'T06'),
    ('чөлөөт гишүүн', 'Олон гишүүнт эсвэл функцийн хувьсагчгүй гишүүн: $y = kx + b$-д $b$, $ax^2 + bx + c$-д $c$. Энэ нь $x = 0$ үеийн функцийн утга буюу графикийн $Oy$-тэй огтлолцох цэгийн ордината.', '$y = x^2 - 3x + 7$-ийн чөлөөт гишүүн $7$', 'T06'),
    ('шугаман функц', '$y = kx + b$ хэлбэрийн функц, энд $k$, $b$ тогтмол тоо. График нь шулуун: $k$ нь өнцгийн коэффициент, $b$ нь $Oy$-тэй огтлолцох цэгийн ордината. $k > 0$ үед өсөх, $k < 0$ үед буурах.', '$y = 2x - 3$: $k = 2$, $b = -3$', 'T06'),
    ('шулууны тэгшитгэл', 'Шулуун дээрх цэгүүдийн координат, зөвхөн тэдгээр нь хангах тэгшитгэл. Налалттай хэлбэр $y = kx + b$; $(x_1; y_1)$ цэг ба налалтаар $y - y_1 = k(x - x_1)$. Босоо шулуун $x = a$ хэлбэртэй.', '$(0; 2)$-ыг дайрсан, $k = 3$: $y = 3x + 2$', 'T06'),
    ('өнцгийн коэффициент', '$y = kx + b$ шулууны $k$ коэффициент; $k = \\tan\\alpha$, энд $\\alpha$ нь шулуун ба $Ox$ тэнхлэгийн эерэг чиглэлийн хоорондох өнцөг. Хоёр цэгээр $k = \\frac{y_2 - y_1}{x_2 - x_1}$. $k > 0$ бол функц өсөх, $k < 0$ бол буурах.', '$y = 3x - 1$-д $k = 3$: $x$ нэгээр өсөхөд $y$ $3$-аар өснө', 'T06'),
    ('өсөх функц', 'Завсар дахь дурын $x_1 < x_2$-ийн хувьд $f(x_1) < f(x_2)$ байвал $f$ энэ завсарт өсөх функц. График зүүнээс баруун тийш дээшилнэ.', '$y = 2x + 1$ бүх тоон шулуун дээр өснө', 'T06'),
    ('буурах', 'Функц $I$ завсарт буурах гэдэг нь $x_1 < x_2$ бүрийн хувьд $f(x_1) > f(x_2)$ байх явдал. $0 < a < 1$ үед $y = a^x$ буурах тул $a^m < a^n \\Leftrightarrow m > n$ — тэнцэтгэл бишийн тэмдэг эргэнэ.', '$y = 0{,}5^x$: $0{,}5^1 > 0{,}5^2$', 'T07'),
    ('ижил суурь', 'Хоёр зэрэг нэг ижил тоон суурьтай байх тохиолдол: $a^m$ ба $a^n$. Ижил суурьтай зэрэгт $a^m \\cdot a^n = a^{m+n}$, $a^m : a^n = a^{m-n}$ дүрэм хэрэглэгдэх ба $a > 0$, $a \\ne 1$ үед $a^m = a^n \\Leftrightarrow m = n$.', '$8^x = 4$: $2^{3x} = 2^2$ болгон ижил суурьт шилжүүлнэ', 'T07'),
    ('илтгэгч тэгшитгэл', 'Үл мэдэгдэгч нь зэргийн илтгэгчид орсон тэгшитгэл, жишээ нь $a^{f(x)} = b$ ($a > 0$, $a \\ne 1$). Үндсэн аргууд: ижил суурьт шилжүүлж $a^{f(x)} = a^{g(x)} \\Leftrightarrow f(x) = g(x)$ ашиглах, $t = a^x$ ($t>0$) орлуулга, логарифмчлах.', '$3^{x-1} = 9 \\Rightarrow x - 1 = 2 \\Rightarrow x = 3$', 'T07'),
    ('илтгэгч тэнцэтгэл биш', 'Үл мэдэгдэгч нь илтгэгчид орсон тэнцэтгэл биш, жишээ нь $a^{f(x)} > a^{g(x)}$. $a > 1$ бол $f(x) > g(x)$ (тэмдэг хадгалагдана), $0 < a < 1$ бол $f(x) < g(x)$ (тэмдэг эргэнэ).', '$0{,}5^x > 4 = 0{,}5^{-2} \\Rightarrow x < -2$', 'T07'),
    ('илтгэгч функц', '$y = a^x$ ($a > 0$, $a \\ne 1$) хэлбэрийн функц. Тодорхойлогдох муж бүх бодит тоо, утгын муж $y > 0$; график $(0; 1)$ цэгийг дайрна. $a > 1$ бол өсөх, $0 < a < 1$ бол буурах.', '$y = 2^x$: $x = -1, 0, 3$ үед $y = \\frac{1}{2}, 1, 8$', 'T07'),
    ('илтгэгч өсөлт', 'Хэмжигдэхүүн тэнцүү хугацаанд тогтмол дахин өсөх процесс: $N(t) = N_0 \\cdot a^t$ ($a > 1$), энд $N_0$ — анхны утга, $a$ — нэгж хугацааны өсөлтийн коэффициент. $0 < a < 1$ бол илтгэгч бууралт болно.', '$N(t) = 50 \\cdot 3^t$: 2 цагийн дараа $50 \\cdot 9 = 450$', 'T07'),
    ('орлуулга', 'Илэрхийллийн нэг хэсгийг шинэ хувьсагчаар тэмдэглэж ($t = g(x)$) бодлогыг хялбар хэлбэрт шилжүүлэх арга. Шинэ хувьсагчийн утгын мужийг ($a^x$-д $t > 0$) заавал тусгаж, эцэст нь буцаан орлуулж $x$-ийг олно.', '$4^x - 3 \\cdot 2^x + 2 = 0$: $t = 2^x$ гэвэл $t^2 - 3t + 2 = 0$', 'T07'),
    ('суурь', '$a^n$ зэргийн давтан үржигдэх $a$ тоо; $n$ нь илтгэгч. Илтгэгч функц $y = a^x$-д суурь $a > 0$, $a \\ne 1$ байх ёстой бөгөөд $a$-гийн утга функцийн өсөх/буурахыг тодорхойлно.', '$5^3 = 5 \\cdot 5 \\cdot 5$: суурь $5$, илтгэгч $3$', 'T07'),
    ('тэг зэрэг', 'Тэгээс ялгаатай дурын тооны тэг зэрэг $1$: $a^0 = 1$ ($a \\ne 0$). Энэ нь $\\frac{a^n}{a^n} = a^{n-n}$ дүрмээс гардаг; $0^0$ тодорхойлогдохгүй.', '$7^0 = 1$, $(-3)^0 = 1$', 'T07'),
    ('өсөх', 'Функц $I$ завсарт өсөх гэдэг нь $x_1 < x_2$ бүрийн хувьд $f(x_1) < f(x_2)$ байх явдал. Илтгэгч функц $y = a^x$ нь $a > 1$ үед бүх тоон шулуун дээр өснө, тиймээс $a^m < a^n \\Leftrightarrow m < n$.', '$y = 3^x$: $3^1 < 3^2$, учир нь $1 < 2$', 'T07'),
    ('lg', 'Аравтын логарифмын тэмдэглэгээ: $\\lg b = \\log_{10} b$, $b > 0$. Натурал логарифм $\\ln b = \\log_e b$-ээс ялгаатай; $\\lg b = c \\Leftrightarrow 10^c = b$.', '$\\lg 100 = 2$, учир нь $10^2 = 100$', 'T08'),
    ('logₐ 1', 'Нэгийн логарифм аль ч зөвшөөрөгдөх сууриар тэг: $\\log_a 1 = 0$ ($a > 0$, $a \\ne 1$), учир нь $a^0 = 1$. Логарифм функцийн график $(1; 0)$ цэгийг дайрдаг нь үүнээс гарна.', '$\\log_7 1 = 0$, $\\lg 1 = 0$', 'T08'),
    ('logₐ a', 'Суурь ба аргумент тэнцүү логарифм: $a > 0$, $a \\ne 1$ үед $\\log_a a = 1$, учир нь $a^1 = a$. Ерөнхийдөө $\\log_a a^n = n$.', '$\\log_5 5 = 1$, $\\lg 10 = 1$', 'T08'),
    ('аравтын логарифм', '10 суурьтай логарифм: $\\lg b = \\log_{10} b$ ($b > 0$). $\\lg 10^n = n$ тул 10-ын бүхэл зэргийн логарифм бүхэл тоо; $0 < b < 1$ үед $\\lg b < 0$.', '$\\lg 1000 = 3$, $\\lg 0{,}1 = -1$', 'T08'),
    ('зэргийн логарифм', 'Зэргийн логарифм нь илтгэгчийг логарифмын өмнө гаргана: $\\log_a b^n = n \\log_a b$ ($a > 0$, $a \\ne 1$, $b > 0$, $n$ — дурын бодит). Язгуурт ч хэрэглэгдэнэ: $\\log_a \\sqrt{b} = \\frac{1}{2} \\log_a b$.', '$\\log_3 9^5 = 5 \\log_3 9 = 10$', 'T08'),
    ('илүү шийд', 'Хувиргалтын явцад (логарифмыг нэгтгэх, квадрат зэрэгт дэвшүүлэх г.м.) тодорхойлогдох муж өргөссөнөөс гарсан, анхны тэгшитгэлийг хангадаггүй язгуур. Иймд язгуур бүрийг ТМ-ээр эсвэл анхны тэгшитгэлд орлуулж шалгаж хаяна.', '$\\lg x + \\lg (x-3) = 1$: $x^2 - 3x - 10 = 0$, $x = -2$ — илүү шийд', 'T08'),
    ('логарифм', '$a > 0$, $a \\ne 1$, $b > 0$ үед $\\log_a b$ нь $a^c = b$ байх цорын ганц $c$ тоо: $\\log_a b = c \\Leftrightarrow a^c = b$. Өөрөөр хэлбэл суурийг $b$ болгохын тулд дэвшүүлэх илтгэгч. Логарифм бол илтгэгч функцийн урвуу үйлдэл.', '$\\log_2 8 = 3$, учир нь $2^3 = 8$', 'T08'),
    ('логарифм тэгшитгэл', 'Үл мэдэгдэгч нь логарифмын аргумент эсвэл сууринд орсон тэгшитгэл. Бодохдоо эхлээд тодорхойлогдох мужийг (аргумент $> 0$, суурь $> 0$, $\\ne 1$) олж, $\\log_a f(x) = c \\Leftrightarrow f(x) = a^c$ эсвэл $\\log_a f = \\log_a g \\Leftrightarrow f = g$ ашиглана. Гарсан язгуурыг ТМ-ээр шүүнэ.', '$\\log_3 (x+1) = 2 \\Rightarrow x + 1 = 9 \\Rightarrow x = 8$', 'T08'),
    ('логарифм тэнцэтгэл биш', 'Үл мэдэгдэгч нь логарифмын дор орсон тэнцэтгэл биш. $a > 1$ бол $\\log_a f > \\log_a g \\Leftrightarrow f > g > 0$, $0 < a < 1$ бол $0 < f < g$ (тэмдэг эргэнэ); тодорхойлогдох мужийг хариунд заавал тусгана.', '$\\log_3 x > 2 \\Rightarrow x > 9$', 'T08'),
    ('логарифмын суурь', '$\\log_a b$ бичлэгийн $a$ тоо — аргументыг гаргахын тулд зэрэгт дэвшүүлэх тоо. Нөхцөл: $a > 0$, $a \\ne 1$; $a > 1$ бол логарифм функц өснө, $0 < a < 1$ бол буурна.', '$\\log_3 9$-ийн суурь $3$; $\\log_1 5$ тодорхойлогдохгүй', 'T08'),
    ('логарифмын чанар', '$a > 0$, $a \\ne 1$, $b, c > 0$ үед хүчинтэй адилтгалууд: $\\log_a (bc) = \\log_a b + \\log_a c$, $\\log_a \\frac{b}{c} = \\log_a b - \\log_a c$, $\\log_a b^n = n \\log_a b$. Мөн $\\log_a a = 1$, $\\log_a 1 = 0$, $a^{\\log_a b} = b$.', '$\\log_2 12 - \\log_2 3 = \\log_2 4 = 2$', 'T08'),
    ('суурь солих', 'Логарифмыг өөр суурьт шилжүүлэх томьёо: $\\log_a b = \\frac{\\log_c b}{\\log_c a}$ ($a, c > 0$, $a, c \\ne 1$, $b > 0$). Онцгой тохиолдол: $\\log_a b = \\frac{1}{\\log_b a}$.', '$\\log_9 27 = \\frac{\\log_3 27}{\\log_3 9} = \\frac{3}{2}$', 'T08'),
    ('тодорхойлолт', 'Ойлголтын утгыг нарийн тогтоосон математикийн өгүүлбэр. Логарифмын сэдэвт гол нь $\\log_a b = c \\Leftrightarrow a^c = b$ ($a > 0$, $a \\ne 1$, $b > 0$) тодорхойлолт бөгөөд энгийн логарифм тэгшитгэлийг шууд зэргийн тэгшитгэлд шилжүүлнэ.', 'Тодорхойлолтоор $\\log_2 x = 5 \\Leftrightarrow x = 2^5$', 'T08'),
    ('ялгаврын логарифм', 'Ижил суурьтай хоёр логарифмын ялгавар нь ноогдворын логарифмтай тэнцүү: $\\log_a b - \\log_a c = \\log_a \\frac{b}{c}$ ($a > 0$, $a \\ne 1$, $b, c > 0$). $\\log_a (b - c)$-тэй андуурч болохгүй.', '$\\log_2 24 - \\log_2 3 = \\log_2 8 = 3$', 'T08'),
    ('үржвэрийн логарифм', 'Эерэг тоонуудын үржвэрийн логарифм нь логарифмуудын нийлбэр: $\\log_a (bc) = \\log_a b + \\log_a c$ ($a > 0$, $a \\ne 1$, $b, c > 0$). $\\log_a (b + c)$-д ийм задаргаа байхгүй.', '$\\log_2 (4 \\cdot 8) = 2 + 3 = 5$', 'T08'),
    ('II мөчлөг', 'Нэгж тойргийн $90^\\circ < \\alpha < 180^\\circ$ өнцгүүдэд харгалзах хэсэг (зүүн дээд дөрөвний нэг). Энд синус эерэг, косинус, тангенс, котангенс сөрөг.', '$150^\\circ$ II мөчлөгт: $\\sin 150^\\circ > 0$, $\\cos 150^\\circ < 0$', 'T09'),
    ('адилтгал хувиргалт', 'Хувьсагчийн тодорхойлогдох мужид илэрхийллийн утгыг өөрчлөхгүйгээр хэлбэрийг нь өөрчлөх хувиргалт. Тригонометрт ихэвчлэн функцуудыг синус, косинусаар илэрхийлж, үндсэн адилтгалыг хэрэглэнэ.', '$\\sin\\alpha \\cdot \\operatorname{ctg}\\alpha = \\sin\\alpha \\cdot \\frac{\\cos\\alpha}{\\sin\\alpha} = \\cos\\alpha$', 'T09'),
    ('ангижруулах томьёо', '$90^\\circ \\pm \\alpha$, $180^\\circ \\pm \\alpha$, $360^\\circ - \\alpha$ гэх мэт өнцгийн тригонометрийн функцийг хурц өнцөг $\\alpha$-ийн функцээр илэрхийлэх томьёо. Тэмдгийг анхны өнцгийн мөчлөг дэх функцийн тэмдгээр тодорхойлно.', '$\\cos 120^\\circ = \\cos(180^\\circ - 60^\\circ) = -\\cos 60^\\circ = -\\frac{1}{2}$', 'T09'),
    ('градус', 'Бүтэн эргэлтийн $\\frac{1}{360}$ хэсэгтэй тэнцүү өнцгийн хэмжээний нэгж. Радиантай $180^\\circ = \\pi$ радиан гэсэн хамаарлаар холбогдоно: $\\alpha^\\circ = \\alpha \\cdot \\frac{\\pi}{180}$ радиан.', '$\\frac{\\pi}{6}$ рад $= \\frac{180^\\circ}{6} = 30^\\circ$', 'T09'),
    ('косинус', 'Тэгш өнцөгт гурвалжны хурц өнцөг $\\alpha$-ийн налсан катетыг гипотенузад харьцуулсан харьцаа: $\\cos\\alpha = \\frac{b}{c}$. Ерөнхийд нь нэгж тойргийн $\\alpha$ өнцөгт харгалзах цэгийн абсциссаар тодорхойлно; утга нь $[-1; 1]$ мужид оршино.', '$\\cos 60^\\circ = \\frac{1}{2}$, $\\cos 180^\\circ = -1$', 'T09'),
    ('котангенс', '$\\operatorname{ctg}\\alpha = \\frac{\\cos\\alpha}{\\sin\\alpha}$, $\\sin\\alpha \\ne 0$ үед тодорхойлогдоно. Тэгш өнцөгт гурвалжинд налсан катетыг эсрэг катетад харьцуулсан харьцаа; $\\operatorname{tg}\\alpha \\cdot \\operatorname{ctg}\\alpha = 1$.', '$\\operatorname{ctg}45^\\circ = 1$, $\\operatorname{ctg}60^\\circ = \\frac{\\sqrt{3}}{3}$', 'T09'),
    ('нэгж тойрог', 'Координатын эх дээр төвтэй, радиус нь $1$ тойрог. $Ox$ тэнхлэгээс цагийн зүүний эсрэг $\\alpha$ өнцгөөр эргүүлсэн цэг $(\\cos\\alpha;\\ \\sin\\alpha)$ координаттай тул дурын өнцгийн синус, косинусыг тодорхойлдог.', '$90^\\circ$-д $(0; 1)$ цэг: $\\cos 90^\\circ = 0$, $\\sin 90^\\circ = 1$', 'T09'),
    ('радиан', 'Нумын урт нь радиустай тэнцүү байх төв өнцгийн хэмжээ. Бүтэн эргэлт $2\\pi$ радиан тул $\\pi$ радиан $= 180^\\circ$, $1$ радиан $\\approx 57{,}3^\\circ$.', '$90^\\circ = \\frac{\\pi}{2}$ рад, $60^\\circ = \\frac{\\pi}{3}$ рад', 'T09'),
    ('синус', 'Тэгш өнцөгт гурвалжны хурц өнцөг $\\alpha$-ийн эсрэг катетыг гипотенузад харьцуулсан харьцаа: $\\sin\\alpha = \\frac{a}{c}$. Ерөнхийд нь нэгж тойргийн $\\alpha$ өнцөгт харгалзах цэгийн ординатаар тодорхойлно; утга нь $[-1; 1]$ мужид оршино.', '$\\sin 30^\\circ = \\frac{1}{2}$, $\\sin 90^\\circ = 1$', 'T09'),
    ('тангенс', '$\\operatorname{tg}\\alpha = \\frac{\\sin\\alpha}{\\cos\\alpha}$, $\\cos\\alpha \\ne 0$ үед тодорхойлогдоно. Тэгш өнцөгт гурвалжинд хурц өнцгийн эсрэг катетыг налсан катетад харьцуулсан харьцаа.', '$\\operatorname{tg}45^\\circ = 1$, $\\operatorname{tg}60^\\circ = \\sqrt{3}$', 'T09'),
    ('тойргийн өнцөг', 'Нэгж тойрог дээр $Ox$ тэнхлэгийн эерэг чиглэлээс эргүүлж хэмжсэн дурын хэмжээтэй өнцөг; цагийн зүүний эсрэг эргэлт эерэг. $360^\\circ$-аас их ба сөрөг өнцөг ч тодорхойлогдоно, $360^\\circ$-аар ялгаатай өнцгүүд нэг цэгт харгалзана.', '$390^\\circ$ ба $30^\\circ$ нэг цэгт харгалзана', 'T09'),
    ('тригонометр тэгшитгэл', 'Үл мэдэгдэгч нь тригонометрийн функцийн аргумент дотор орсон тэгшитгэл. Функцууд үелэх тул шийд олон байдаг; өгсөн завсар дахь бүх шийдийг нэгж тойргоор олно.', '$\\cos x = 0$, $[0; 2\\pi]$ завсарт: $x = \\frac{\\pi}{2}$; $x = \\frac{3\\pi}{2}$', 'T09'),
    ('тригонометрийн үндсэн адилтгал', 'Ямар ч $\\alpha$ өнцгийн хувьд $\\sin^2\\alpha + \\cos^2\\alpha = 1$ биелнэ — нэгж тойрог дээрх Пифагорын теорем. Нэг функцийн утгаас нөгөөгийнхийг олоход хэрэглэх ба тэмдгийг өнцгийн мөчлөгөөр сонгоно.', '$\\sin\\alpha = 0{,}6$, $\\alpha$ хурц бол $\\cos\\alpha = \\sqrt{1 - 0{,}36} = 0{,}8$', 'T09'),
    ('тусгай өнцөг', 'Тригонометрийн функцийн утга нь язгуураар яг илэрхийлэгддэг $0^\\circ$, $30^\\circ$, $45^\\circ$, $60^\\circ$, $90^\\circ$ өнцгүүд. Утгыг нь тэгш талт ба тэгш өнцөгт адил хажуут гурвалжнаас гаргадаг тул цээжлэх шаардлагатай.', '$\\sin 45^\\circ = \\cos 45^\\circ = \\frac{\\sqrt{2}}{2}$', 'T09'),
    ('хурц өнцөг', '$0^\\circ$-аас их, $90^\\circ$-аас бага өнцөг ($0 < \\alpha < \\frac{\\pi}{2}$). Нэгж тойргийн I мөчлөгт оршдог тул бүх тригонометрийн функц нь эерэг утгатай.', '$\\alpha = 40^\\circ$ хурц тул $\\sin\\alpha > 0$, $\\cos\\alpha > 0$', 'T09'),
    ('хялбарчлах', 'Илэрхийллийг адилтгал хувиргалтаар түүнтэй тэнцүү, илүү энгийн хэлбэрт шилжүүлэх. Хувиргалт бүр тодорхойлогдох мужид хүчинтэй байх ёстой, жишээ нь тэгээс ялгаатай үржигдэхүүнийг л хураана.', '$\\frac{\\sin^2\\alpha}{\\sin\\alpha} = \\sin\\alpha$ ($\\sin\\alpha \\ne 0$)', 'T09'),
    ('үелэх чанар', '$f(x + T) = f(x)$ бүх $x$-д биелэх $T \\ne 0$ тоо оршдог бол $f$ үелэх функц, хамгийн бага эерэг $T$ нь үе. Синус, косинусын үе $2\\pi$ ($360^\\circ$), тангенсынх $\\pi$.', '$\\sin 390^\\circ = \\sin(30^\\circ + 360^\\circ) = \\sin 30^\\circ$', 'T09'),
    ('үндсэн адилтгал', 'Тригонометрийн үндсэн адилтгал: ямар ч $\\alpha$-д $\\sin^2\\alpha + \\cos^2\\alpha = 1$. Үүнээс $1 + \\operatorname{tg}^2\\alpha = \\frac{1}{\\cos^2\\alpha}$ зэрэг бусад адилтгал гарна.', '$(1-\\sin\\alpha)(1+\\sin\\alpha) = 1 - \\sin^2\\alpha = \\cos^2\\alpha$', 'T09'),
    ('Бернуллийн схем', '$A$ үзэгдэл бүрт ижил $p$ магадлалтай $n$ бие даасан туршилтын дараалал. $A$ яг $k$ удаа биелэх магадлал $P_n(k) = C_n^k p^k (1-p)^{n-k}$.', 'Зоосыг $3$ удаа: $P_3(2) = C_3^2 \\cdot \\frac{1}{8} = \\frac{3}{8}$', 'T10'),
    ('байрлуулал', '$n$ ялгаатай элементээс $k$-г сонгож, дарааллыг нь харгалзан байрлуулсан эрэмбэлэгдсэн цуваа. Тоо нь $A_n^k = \\frac{n!}{(n-k)!} = n(n-1)\\cdots(n-k+1)$.', '$5$ гүйгчээс 1, 2-р байр: $A_5^2 = 5 \\cdot 4 = 20$', 'T10'),
    ('бие даасан туршилт', 'Нэг туршилтын үр дүн нөгөө туршилтын үр дүнгийн магадлалд нөлөөлдөггүй туршилтууд. Ийм туршилтуудын үр дүнгүүд зэрэг гарах магадлал нь тус бүрийн магадлалын үржвэртэй тэнцүү.', 'Зоосыг $3$ удаа хаяхад ССС: $(\\frac{1}{2})^3 = \\frac{1}{8}$', 'T10'),
    ('бие даасан үзэгдэл', 'Нэг нь биелэх эсэх нь нөгөөгийнх нь магадлалд нөлөөлдөггүй үзэгдлүүд. Тодорхойлолтоор $A$, $B$ бие даасан нь $P(A \\cap B) = P(A) \\cdot P(B)$ байх явдал.', 'Хоёр зоосонд хоёулаа сүлд: $\\frac{1}{2} \\cdot \\frac{1}{2} = \\frac{1}{4}$', 'T10'),
    ('боломжит үр дүн', 'Туршилтын үед гарч болох, хоорондоо давхцахгүй энгийн үр дүн бүр. Бүх боломжит үр дүнгийн тоо $n$ нь сонгодог магадлалын томьёоны хуваарь болно.', 'Зоос хаяхад: сүлд, тоо — $n = 2$', 'T10'),
    ('боломжит үр дүнгийн огторгуй', 'Туршилтын бүх боломжит энгийн үр дүнгийн олонлог, ихэвчлэн $\\Omega$ гэж тэмдэглэнэ. Үзэгдэл бүр нь $\\Omega$-ийн дэд олонлог бөгөөд $P(\\Omega) = 1$.', 'Хоёр шоо: $\\Omega = \\{(a; b)\\}$, $|\\Omega| = 6 \\cdot 6 = 36$', 'T10'),
    ('буцаалгүй сонголт', 'Авсан элементийг буцааж хийлгүйгээр дараагийн элементийг сонгох арга. Авалт бүр олонлогийн бүрэлдэхүүнийг өөрчилдөг тул дараагийн магадлал нөхцөлт магадлал болж, үзэгдлүүд бие даасан биш.', '$4$ улаан, $1$ цагаанаас $2$ улаан: $\\frac{4}{5} \\cdot \\frac{3}{4} = \\frac{3}{5}$', 'T10'),
    ('дараалал чухал', 'Ижил элементүүдийн байрлалын дарааллыг өөрчлөхөд өөр үр дүн гарах тохиолдол. Ийм сонголтыг байрлуулал $A_n^k$ эсвэл сэлгэмэл $P_n$-ээр тоолно.', 'Ахлагч А, орлогч Б ба эсрэгээр нь — $2$ өөр хуваарилалт', 'T10'),
    ('дараалал чухал биш', 'Сонгосон элементүүдийн байрлалын дарааллыг өөрчлөхөд шинэ сонголт үүсэхгүй тохиолдол. Ийм сонголтыг хэсэглэл $C_n^k$-аар тоолно.', 'А, Б ба Б, А нь нэг баг; $4$ хүнээс $2$: $C_4^2 = 6$', 'T10'),
    ('комбинаторик', 'Төгсгөлөг олонлогийн элементүүдийг тодорхой нөхцөлөөр сонгох, байрлуулах аргуудын тоог судалдаг математикийн салбар. Үндсэн хэрэгсэл нь нэмэх ба үржүүлэх дүрэм, сэлгэмэл, байрлуулал, хэсэглэл.', '$4$ үсгийг $4! = 24$ янзаар өрнө', 'T10'),
    ('магадлал', 'Үзэгдэл биелэх боломжийн тоон хэмжүүр, $0 \\le P(A) \\le 1$. Бүх үр дүн адил боломжтой үед сонгодог тодорхойлолт $P(A) = \\frac{m}{n}$, энд $m$ — таатай, $n$ — бүх боломжит үр дүнгийн тоо.', 'Шоо хаяхад $6$ буух: $P = \\frac{1}{6}$', 'T10'),
    ('магадлалын үржвэр', 'Хоёр үзэгдэл зэрэг биелэх магадлалын томьёо: $P(A \\cap B) = P(A) \\cdot P(B \\mid A)$. $A$, $B$ бие даасан бол $P(B \\mid A) = P(B)$ тул $P(A \\cap B) = P(A) \\cdot P(B)$.', 'Хоёр шоонд хоёулаа $6$: $\\frac{1}{6} \\cdot \\frac{1}{6} = \\frac{1}{36}$', 'T10'),
    ('нийцтэй үзэгдэл', 'Нэг туршилтад зэрэг биелж болох ($A \\cap B \\ne \\varnothing$) үзэгдлүүд. Тэдгээрийн нэгдлийн магадлалыг $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$-ээр олно.', 'Шоонд «тэгш» ба «3-т хуваагдах» хоёулаа $6$-д биелнэ', 'T10'),
    ('сэлгэмэл', '$n$ ялгаатай элементийг бүгдийг нь тодорхой дарааллаар байрлуулсан нэг байрлал. Бүх сэлгэмлийн тоо $P_n = n!$ бөгөөд үржүүлэх дүрмээс гарна.', '$3$ номыг тавиурт $P_3 = 3! = 6$ янзаар өрнө', 'T10'),
    ('таатай үр дүн', 'Туршилтын боломжит үр дүнгүүдээс тухайн $A$ үзэгдэл биелэхэд хүргэдэг үр дүн. Таатай үр дүнгийн тоо $m$ нь сонгодог магадлалын $P(A) = \\frac{m}{n}$ томьёоны хүртвэр болно.', 'Шоонд тэгш тоо буух: таатай нь $2, 4, 6$ — $m = 3$', 'T10'),
    ('факториал', 'Натурал $n$-ийн факториал нь $1$-ээс $n$ хүртэлх бүх натурал тооны үржвэр: $n! = 1 \\cdot 2 \\cdot \\ldots \\cdot n$; тохиролцоогоор $0! = 1$. Рекуррент хамаарал $n! = n \\cdot (n-1)!$ биелнэ.', '$4! = 1 \\cdot 2 \\cdot 3 \\cdot 4 = 24$', 'T10'),
    ('хуваагдах', 'Бүхэл $a$ тоо бүхэл $b \\ne 0$ тоонд хуваагдана гэдэг нь $a = b \\cdot k$ байх бүхэл $k$ оршино гэсэн үг, $b \\mid a$ гэж тэмдэглэнэ. Өөрөөр хэлбэл $a$-г $b$-д хуваахад үлдэгдэл $0$.', '$3 \\mid 9$, учир нь $9 = 3 \\cdot 3$; $10$ нь $3$-т хуваагдахгүй', 'T10'),
    ('хэсэглэл', '$n$ ялгаатай элементээс дараалал харгалзахгүйгээр сонгосон $k$ элементтэй дэд олонлог. Тоо нь $C_n^k = \\frac{n!}{k!\\,(n-k)!}$, мөн $C_n^k = C_n^{n-k}$.', '$5$ хүнээс $2$-ыг: $C_5^2 = \\frac{5 \\cdot 4}{2} = 10$', 'T10'),
    ('эсрэг үзэгдэл', '$A$ үзэгдэл биелэхгүй байх үзэгдэл, $\\bar A$ гэж тэмдэглэнэ. $A$ ба $\\bar A$ үл нийцэх бөгөөд нийлээд бүх огторгуйг бүрдүүлэх тул $P(\\bar A) = 1 - P(A)$.', '$P(A) = 0{,}2$ бол $P(\\bar A) = 0{,}8$', 'T10'),
    ('үржүүлэх дүрэм', 'Эхний алхмыг $m$ янзаар, тэр бүрд хоёр дахь алхмыг $n$ янзаар хийж болох бол хоёр алхмыг дараалан $m \\cdot n$ янзаар хийнэ. Олон алхамтай үед ч сонголтын тоонуудыг үржүүлнэ.', '$3$ цамц, $2$ малгай: $3 \\cdot 2 = 6$ хослол', 'T10'),
]
